import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"关于与更新","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/about.md","filePath":"zh-CN/user-guide/settings/about.md","lastUpdated":1787586465000}'),s={name:"zh-CN/user-guide/settings/about.md"};function i(n,a,l,d,c,h){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="关于与更新" tabindex="-1">关于与更新 <a class="header-anchor" href="#关于与更新" aria-label="Permalink to &quot;关于与更新&quot;">​</a></h1><p>关于页面提供了 Lertaro 当前运行环境的完整版本信息、用户与系统数据存储目录的快速直达入口，以及在线检查更新与一键无缝升级功能。页面路径为<strong>设置 → 关于</strong>。</p><h2 id="_1-组件版本与项目信息" tabindex="-1">1. 组件版本与项目信息 <a class="header-anchor" href="#_1-组件版本与项目信息" aria-label="Permalink to &quot;1. 组件版本与项目信息&quot;">​</a></h2><p>页面顶部展示了 Lertaro 架构体系中四大核心组件的独立版本号：</p><ul><li><strong>App 版本</strong>：前台 WPF 用户交互界面版本。</li><li><strong>Core 版本</strong>：核心搜索与索引计算逻辑库版本。</li><li><strong>Service 版本</strong>：后台 Windows 索引服务版本（其文字颜色会动态反映服务当前是否处于健康连接状态）。</li><li><strong>CLI 版本</strong>：命令行终端交互工具 <code>lff</code> 的版本。</li></ul><p>下方提供了项目官方网站、GitHub 开源仓库以及在线文档中心的直达链接。</p><h2 id="_2-数据目录与自动备份轮转机制" tabindex="-1">2. 数据目录与自动备份轮转机制 <a class="header-anchor" href="#_2-数据目录与自动备份轮转机制" aria-label="Permalink to &quot;2. 数据目录与自动备份轮转机制&quot;">​</a></h2><p>页面中央提供了两个直接可点击打开物理路径的超链接（若目标文件夹尚未生成，点击时会自动创建）：</p><h3 id="用户数据目录-user-data-directory" tabindex="-1">用户数据目录（User Data Directory） <a class="header-anchor" href="#用户数据目录-user-data-directory" aria-label="Permalink to &quot;用户数据目录（User Data Directory）&quot;">​</a></h3><ul><li><strong>存储内容</strong>：存放当前 Windows 用户的个人配置文件 <code>user-settings.json</code>、搜索与关键字历史记录、用户专属缓存及证书。</li><li><strong>五级备份轮转保护机制</strong>：每次在设置中心点击保存或修改配置时，Lertaro 会自动将现有配置文件顺延轮转备份为 <code>user-settings.json.bak.1</code>，旧的备份依次向后推移至 <code>user-settings.json.bak.5</code>。即使发生断电、误改或系统崩溃，也能随时在数据目录中找到最近 5 次的历史备份进行恢复。</li></ul><h3 id="机器数据目录-machine-data-directory" tabindex="-1">机器数据目录（Machine Data Directory） <a class="header-anchor" href="#机器数据目录-machine-data-directory" aria-label="Permalink to &quot;机器数据目录（Machine Data Directory）&quot;">​</a></h3><ul><li><strong>存储内容</strong>：存放后台提权服务使用的机器级配置文件 <code>machine-settings.json</code>、全盘物理索引持久化缓存以及服务端日志。</li></ul><h3 id="存储路径规则" tabindex="-1">存储路径规则 <a class="header-anchor" href="#存储路径规则" aria-label="Permalink to &quot;存储路径规则&quot;">​</a></h3><ul><li><strong>安装版</strong>：用户数据存放于 <code>%LocalAppData%\\Lertaro</code>，机器数据存放于 <code>%ProgramData%\\Lertaro</code>。</li><li><strong>便携版</strong>：用户数据存放于程序目录下的 <code>Data\\Users\\&lt;SID hash&gt;</code>，机器数据存放于 <code>Data\\Machine</code>，实现纯绿色的全隔离便携运行（详见<a href="./../getting-started.html#便携版数据隔离机制"><strong>便携版使用说明</strong></a>）。</li></ul><h2 id="_3-检查更新与一键升级" tabindex="-1">3. 检查更新与一键升级 <a class="header-anchor" href="#_3-检查更新与一键升级" aria-label="Permalink to &quot;3. 检查更新与一键升级&quot;">​</a></h2><ul><li><strong>检查更新按钮</strong>：点击后手动发起在线版本检测。按钮文字会动态反馈检查状态（“正在检查更新...” → “已是最新版本” 或弹出新版本更新卡片）。</li><li><strong>发现新版本时的升级方式</strong>： <ul><li><strong>静默自动更新</strong> —— 在后台自动下载新版本安装包并就地无缝覆盖升级，升级完成后自动重启拉起 Lertaro。</li><li><strong>前往下载页面</strong> —— 在默认浏览器中打开 GitHub Releases 发布页面，供手动下载便携压缩包或安装程序。</li></ul></li><li><strong>权限安全提示</strong>：若当前运行在受限的标准用户账户下，且无法直接停用后台 Windows 服务完成就地更新，页面会呈现醒目的安全提示，并引导你前往官方页面下载安装。</li></ul>',16)])])}const _=t(s,[["render",i]]);export{g as __pageData,_ as default};
